-- 세트 111: Vault 백업과 복원: 스냅샷으로 되살리기
-- Vault 세트(docs/specs/spec_content_reinforcement.md). 정답·해설은 서버만 안다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (111, 1, '왜 백업이 필요할까?', 'Vault 는 조직의 비밀이 모두 모이는 곳입니다. 저장소 데이터가 사라지면 어떻게 될까요?', '비밀을 다시 만들 수 없다면 어떤 일이 생길지 상상해 보세요.', NULL, NULL, '[]', 'choice', '["아무 문제 없다. 앱이 알아서 복구한다", "비밀이 자동으로 재생성된다", "저장된 비밀을 되살릴 방법이 없어, 이를 쓰던 서비스들이 한꺼번에 멈출 수 있다. 그래서 정기 백업(스냅샷)이 필수다", "다음 날 저절로 돌아온다"]', 2, '맞아요! Vault 데이터는 다른 곳에 사본이 없을 수 있어서, 스냅샷이 유일한 생명줄이 되기도 해요.', NULL, NULL, NULL, NULL),
  (111, 2, '스냅샷 저장·복원 명령', 'Raft 저장소를 쓰는 Vault 에서 ① 스냅샷을 **저장**하고, ② 스냅샷으로 **복원**하는 명령입니다. 빈칸을 채워 보세요.', '저장은 save, 되살리기는 restore 예요.', NULL, NULL, '[]', 'fill', '["save", "restore", "list", "join"]', NULL, '`snapshot save 파일` 로 현재 상태를 한 파일에 담고, `snapshot restore 파일` 로 그 시점으로 되돌려요. 파일 하나가 금고 전체이니 소중히 다뤄야 해요.', '[0, 1]', 'vault operator raft snapshot {0} /backup/vault.snap
vault operator raft snapshot {1} /backup/vault.snap', NULL, NULL),
  (111, 3, '스냅샷 파일은 민감할까?', '`vault.snap` 파일을 어떻게 다뤄야 할까요?', '이 파일 하나에 비밀이 모두 담겨 있어요.', NULL, NULL, '[]', 'choice', '["아무나 읽어도 괜찮은 일반 로그 파일이다", "비밀이 담긴 매우 민감한 파일이므로 접근 권한을 제한하고, 안전한 저장소에 암호화해서 보관한다", "메신저로 팀원에게 나눠 준다", "공개 저장소에 올려 둔다"]', 1, '스냅샷은 Vault 의 데이터를 통째로 담고 있어요. 파일 접근 권한, 저장 위치, 전송 방법 모두 금고를 다루듯이 조심해요.', NULL, NULL, NULL, NULL),
  (111, 4, '스냅샷 복원 순서', '문제가 생겨 스냅샷으로 복원하는 흐름을 **앞에서 뒤**로 놓아 보세요.', '지금 상태를 확인하고, 파일을 믿을 수 있는지 보고, 복원하고, 열고, 확인해요.', NULL, NULL, '[]', 'order', '["복원 후 봉인 상태를 확인하고 필요하면 unseal 한 뒤, 비밀을 읽어 정상인지 검증한다", "`vault status` 로 현재 상태를 확인한다", "`vault operator raft snapshot restore 파일` 로 복원한다", "복원할 스냅샷 파일이 어느 시점의 것인지, 손상되지 않았는지 확인한다"]', NULL, '**상태 확인 → 스냅샷 확인 → 복원 → unseal·검증** 입니다. 복원은 현재 데이터를 되돌리는 작업이라 서두르지 말고 확인부터 하세요.', '[1, 3, 2, 0]', NULL, NULL, NULL),
  (111, 5, '복원 후 unseal 키', '스냅샷을 복원한 뒤 Vault 가 `Sealed` 상태입니다. 어떤 키가 필요할까요?', '스냅샷을 떴을 때의 금고 열쇠와 연결되어 있어요.', NULL, NULL, '[]', 'choice', '["아무 키나 된다", "키가 필요 없다", "새 키가 자동으로 만들어진다", "스냅샷을 뜬 시점의 unseal 키(또는 그 시점 이후 키를 바꿨다면 해당 키 정보)가 필요하다. 그래서 unseal 키도 안전하게 보관해야 한다"]', 3, '스냅샷은 백업이지 열쇠가 아니에요. 열쇠(unseal 키)를 잃으면 백업이 있어도 열 수 없으니, 키와 백업을 따로 보관해야 해요.', NULL, NULL, NULL, NULL),
  (111, 6, '매일 새벽 2시에 실행', '매일 새벽 **2시 0분**에 스냅샷을 저장하는 cron 의 시간 부분입니다. (분 시 일 월 요일 순서)', 'cron 은 "분 시 일 월 요일" 순서예요. 분이 먼저입니다.', NULL, NULL, '[]', 'fill', '["0", "2", "*", "30"]', NULL, '`0 2 * * *` 는 "매일 2시 0분"이에요. 파일 이름에 날짜(`$(date +%F)`)를 넣으면 날마다 다른 파일이 생겨 덮어쓰지 않아요.', '[0, 1]', '{0} {1} * * *  vault operator raft snapshot save /backup/vault-$(date +%F).snap', NULL, NULL),
  (111, 7, '백업을 어디에 둘까?', '스냅샷을 Vault 서버와 **같은 디스크**에만 저장하면 어떤 위험이 있을까요?', '서버가 고장 나면 같은 곳에 있던 것들은 어떻게 될까요?', NULL, NULL, '[]', 'choice', '["아무 위험이 없다", "서버나 디스크가 고장 나면 원본과 백업이 함께 사라진다. 다른 서버·저장소로도 복사해 두어야 한다", "백업이 더 빨라진다", "디스크가 더 튼튼해진다"]', 1, '백업은 "원본과 다른 곳"에 있어야 의미가 있어요. 보관 기간도 정하고 오래된 것은 정리해요.', NULL, NULL, NULL, NULL),
  (111, 8, '백업 운영 사이클', '백업을 건강하게 운영하는 흐름을 **앞에서 뒤**로 놓아 보세요.', '만들고, 옮기고, 정리하고, 정말 되는지 확인해 봅니다.', NULL, NULL, '[]', 'order', '["주기적으로 테스트 환경에서 복원 연습을 해서 정말 되는지 확인한다", "정해진 보관 기간이 지난 오래된 스냅샷을 정리한다", "스냅샷을 정기적으로 저장한다", "저장한 스냅샷을 다른 안전한 저장소로 복사한다"]', NULL, '**저장 → 다른 곳으로 복사 → 오래된 것 정리 → 복원 연습** 입니다. 마지막의 복원 연습이 빠지면 백업이 쓸모 있는지 모르는 채로 지내게 돼요.', '[2, 3, 1, 0]', NULL, NULL, NULL),
  (111, 9, '복원 연습을 하는 이유', '"백업은 잘 되고 있다"는데 복원 연습을 해 본 적이 없습니다. 어떤 점이 걱정일까요?', '필요한 순간에 처음 열어 봤는데 안 열리면 어떻게 될까요?', NULL, NULL, '[]', 'choice', '["걱정할 것이 없다", "복원 연습은 데이터를 지운다", "백업 속도가 느려진다", "막상 필요한 날 파일이 손상됐거나 절차·키를 몰라 복원하지 못하는 일이 생길 수 있다. 복원해 본 적 없는 백업은 믿을 수 없다"]', 3, '복원 연습은 절차를 몸에 익히고 시간을 재 보는 기회이기도 해요. 분기마다 한 번만이라도 해 두면 큰 도움이 됩니다.', NULL, NULL, NULL, NULL),
  (111, 10, '비밀이 유출됐을 때', '비밀번호가 유출된 것 같습니다. 어제 뜬 스냅샷으로 복원하면 해결될까요?', '복원은 과거 상태로 되돌릴 뿐이에요.', NULL, NULL, '[]', 'choice', '["맞다. 복원하면 유출이 취소된다", "아니다. 복원은 과거 상태로 되돌릴 뿐 유출된 비밀이 사라지지 않는다. 해당 비밀을 폐기(revoke)하고 새 값으로 교체(rotate)해야 한다", "스냅샷을 한 번 더 뜨면 된다", "Vault 를 재설치하면 된다"]', 1, '이미 새어 나간 비밀은 되돌릴 수 없어요. 그 비밀을 못 쓰게 만들고 새 값으로 바꾸는 것이 우선이에요.', NULL, NULL, NULL, NULL),
  (111, 11, '복원 후 Sealed 일 때 대응', '복원 후 `vault status` 가 `Sealed true` 입니다. 대응 순서를 **앞에서 뒤**로 놓아 보세요.', '상태 확인 → 키 입력 → 상태 재확인 → 검증 순서예요.', NULL, NULL, '[]', 'order', '["`vault status` 로 `Sealed false` 가 되었는지 다시 확인한다", "정해진 수의 unseal 키를 `vault operator unseal` 로 넣는다", "대표적인 비밀 몇 개를 읽어 복원 결과가 정상인지 검증한다", "`vault status` 로 `Sealed true` 와 필요한 키 개수(Threshold)를 확인한다"]', NULL, '**상태·필요 키 수 확인 → unseal → 다시 status → 비밀 읽어 검증** 입니다. 한 단계씩 확인하면 조급한 상황에서도 실수를 줄일 수 있어요.', '[3, 1, 0, 2]', NULL, NULL, NULL);
